    const camera = this.cameras.main;
    const minimapLeft = VIEW_WIDTH - MINIMAP_MARGIN - map.widthTiles * MINIMAP_SCALE;
    this.minimapMarks.clear();

    const drawn: DrawnShip[] = [];
    const present = new Set<string>();
    for (const ship of this.view.ships()) {
      const position = this.view.renderPosition(ship.id, now);
      if (position === undefined) continue;
      present.add(ship.id);
      const mine = ship.id === this.view.selfId;
      let graphics = this.shipGraphics.get(ship.id);
      if (graphics === undefined) {
        graphics = this.drawShip(slotColor(ship.slot), mine);
        this.shipGraphics.set(ship.id, graphics);
      }
      const x = position.x * PIXELS_PER_SUB_UNIT;
      const y = position.y * PIXELS_PER_SUB_UNIT;
      graphics.setPosition(x, y);
      graphics.setRotation((ship.heading * 2 * Math.PI) / HEADING_COUNT);
      drawn.push({ id: ship.id, x: Math.round(x - camera.scrollX), y: Math.round(y - camera.scrollY), color: cssColor(slotColor(ship.slot)) });
      this.minimapMarks.fillStyle(mine ? OWN_RING_COLOR : slotColor(ship.slot), 1);
      this.minimapMarks.fillRect(minimapLeft + (x / TILE_PIXELS) * MINIMAP_SCALE - 1.5, MINIMAP_MARGIN + (y / TILE_PIXELS) * MINIMAP_SCALE - 1.5, 3, 3);
    }
    for (const [id, graphics] of this.shipGraphics) {
      if (present.has(id)) continue;
      graphics.destroy();
      this.shipGraphics.delete(id);
    }
    const report = JSON.stringify(drawn);
    if (report !== this.lastReport) {
      this.report.dataset["drawnShips"] = report;
      this.lastReport = report;
    }
    this.report.dataset["camera"] = `${camera.scrollX},${camera.scrollY}`;
  }

  /** A round hull with a bow pointing along +x; the player's own ship gets a pale ring. */
  private drawShip(color: number, own: boolean): Phaser.GameObjects.Graphics {
    const graphics = this.add.graphics();
    graphics.setDepth(2);
    graphics.fillStyle(color, 1);
    graphics.fillCircle(0, 0, 6);
    graphics.fillTriangle(3, -5, 12, 0, 3, 5);
    if (own) {
      graphics.lineStyle(2, OWN_RING_COLOR, 1);
      graphics.strokeCircle(0, 0, 10);
    }
    return graphics;
  }
}

export function startGame(parent: HTMLElement, view: MatchView): Phaser.Game {
  return new Phaser.Game({
    type: Phaser.AUTO,
    parent,
    width: VIEW_WIDTH,
    height: VIEW_HEIGHT,
    backgroundColor: SEA_COLOR,
    banner: false,
    audio: { noAudio: true },
    scene: new SeaScene(view, parent),
  });
}
/**
 * The minimap's fog (§3): every tile starts hidden, and tiles within the sight radius of the player's ship are
 * revealed for good as it sails. Terrain is public content, so this is presentation only, not a security boundary
 * (§16); ships are filtered by the server.
 */
export class FogOfWar {
  private readonly revealed: Uint8Array;
  private count = 0;
  private lastTile = -1;

  constructor(
    readonly widthTiles: number,
    readonly heightTiles: number,
    readonly radiusTiles: number,
  ) {
    this.revealed = new Uint8Array(widthTiles * heightTiles);
  }

  get revealedCount(): number {
    return this.count;
  }

  isRevealed(tileX: number, tileY: number): boolean {
    return this.revealed[tileY * this.widthTiles + tileX] === 1;
  }

  /** Reveals the disc around a tile and returns the tiles it newly revealed, as `[tileX, tileY]` pairs. */
  revealAround(tileX: number, tileY: number): [number, number][] {
    const centre = tileY * this.widthTiles + tileX;
    if (centre === this.lastTile) return [];
    this.lastTile = centre;
    const fresh: [number, number][] = [];
    const radius = this.radiusTiles;
    for (let dy = -radius; dy <= radius; dy++) {
      for (let dx = -radius; dx <= radius; dx++) {
        if (dx * dx + dy * dy > radius * radius) continue;
        const x = tileX + dx;
        const y = tileY + dy;
        if (x < 0 || y < 0 || x >= this.widthTiles || y >= this.heightTiles) continue;
        const index = y * this.widthTiles + x;
        if (this.revealed[index] === 1) continue;
        this.revealed[index] = 1;
        this.count++;
        fresh.push([x, y]);
      }
    }
    return fresh;
  }
}
import { Buttons } from "@pirate-sea-race/protocol";

/** What the player asks of their ship: protocol axes (moveX turns, moveY is the throttle, up ahead) and buttons. */
export interface Helm {
  readonly moveX: number;
  readonly moveY: number;
  readonly buttons: number;
}

export const NEUTRAL_HELM: Helm = { moveX: 0, moveY: 0, buttons: 0 };

const KEYS = {
  left: ["KeyA", "ArrowLeft"],
  right: ["KeyD", "ArrowRight"],
  up: ["KeyW", "ArrowUp"],
  down: ["KeyS", "ArrowDown"],
  interact: ["KeyE"],
} as const;

const HELM_CODES = new Set<string>(Object.values(KEYS).flat());

/** Converts two opposing keys into one axis: both held is neutral, whatever order they were pressed in (§8). */
export function axis(negative: boolean, positive: boolean): number {
  return (positive ? 1 : 0) - (negative ? 1 : 0);
}

/**
 * The keyboard input adapter (§8 defaults): up is throttle, down brakes (and reverses slowly from a stop), left and
 * right turn, E interacts (docks). It tracks held keys and releases them all when the window loses focus, so a ship
 * never keeps sailing on a key-up the page missed.
 */
export class KeyboardHelm {
  private readonly held = new Set<string>();

  constructor(target: Window) {
    target.addEventListener("keydown", (event) => {
      if (!HELM_CODES.has(event.code) || isTyping(event.target)) return;
      event.preventDefault();
      this.held.add(event.code);
    });
    target.addEventListener("keyup", (event) => {
      this.held.delete(event.code);
    });
    target.addEventListener("blur", () => this.held.clear());
  }

  helm(): Helm {
    const any = (codes: readonly string[]) => codes.some((code) => this.held.has(code));
    return {
      moveX: axis(any(KEYS.left), any(KEYS.right)),
      moveY: axis(any(KEYS.up), any(KEYS.down)),
      buttons: any(KEYS.interact) ? Buttons.Interact : 0,
    };
  }
}

function isTyping(target: EventTarget | null): boolean {
  return target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement;
}
import { DUEL_INPUT } from "@pirate-sea-race/content/moves";

/** The duel's keyboard defaults (§8): WASD or the arrows move, J light, K heavy, U and I the specials, Shift dash. */
export const DUEL_KEYS: Readonly<Record<keyof typeof DUEL_INPUT, readonly string[]>> = {
  left: ["KeyA", "ArrowLeft"],
  right: ["KeyD", "ArrowRight"],
  up: ["KeyW", "ArrowUp"],
  down: ["KeyS", "ArrowDown"],
  light: ["KeyJ"],
  heavy: ["KeyK"],
  special1: ["KeyU"],
  special2: ["KeyI"],
  dash: ["ShiftLeft", "ShiftRight"],
};

const BIT_OF_CODE = new Map<string, number>(
  (Object.entries(DUEL_KEYS) as [keyof typeof DUEL_INPUT, readonly string[]][]).flatMap(([name, codes]) => codes.map((code) => [code, DUEL_INPUT[name]] as const)),
);

/** The input bits for a set of held key codes. Opposite directions both held stay in: the step makes them neutral. */
export function duelBits(codes: Iterable<string>): number {
  let bits = 0;
  for (const code of codes) bits |= BIT_OF_CODE.get(code) ?? 0;
  return bits;
}

/**
 * The duel's keyboard adapter. `bits()` is what is held now, plus every key pressed since the last frame the client
 * tagged: a tap that goes down and up between two frames still counts for one frame. The caller calls `framesTagged()`
 * once the pressed keys have been tagged into a frame. Every key is released when the window loses focus.
 */
export class DuelKeyboard {
  private readonly held = new Set<string>();
  private tapped = 0;

  constructor(target: Window) {
    target.addEventListener("keydown", (event) => {
      if (!BIT_OF_CODE.has(event.code) || isTyping(event.target)) return;
      event.preventDefault();
      this.press(event.code);
    });
    target.addEventListener("keyup", (event) => this.release(event.code));
    target.addEventListener("blur", () => this.held.clear());
  }

  press(code: string): void {
    this.held.add(code);
    this.tapped |= BIT_OF_CODE.get(code) ?? 0;
  }

  release(code: string): void {
    this.held.delete(code);
  }

  bits(): number {
    return duelBits(this.held) | this.tapped;
  }

  /** The keys pressed so far have made it into a tagged frame; a tap released since then no longer counts. */
  framesTagged(): void {
    this.tapped = 0;
  }
}

/** Keys typed into a text field or a menu are not moves; a checkbox or a button does not take them. */
function isTyping(target: EventTarget | null): boolean {
  if (target instanceof HTMLInputElement) return target.type !== "checkbox" && target.type !== "button";
  return target instanceof HTMLTextAreaElement || target instanceof HTMLSelectElement;
}

