import { z } from "zod";
import { matchCodeSchema } from "./join.js";

/**
 * Test-only ship placement. Browser and integration tests put ships where a scenario needs them (in sight of each
 * other, out of sight, behind a shoal) instead of relying on random spawn slots. The server offers the route only when
 * its entry point reads TEST_PLACEMENT_ENV as "1" (the dev and test entries; never the production `main`), and it is
 * off by default. It moves a ship and nothing else: admission and per-client visibility are unchanged.
 */
export const TEST_PLACEMENT_ENV = "PIRATE_SEA_RACE_TEST_PLACEMENT";
export const TEST_PLACEMENT_PATH = "/__test/place";

/**
 * The headings a placement may name: the simulation's HEADING_COUNT, which lives in the content package the protocol
 * does not depend on. A server unit test (`apps/server/src/testPlacement.test.ts`) keeps the two equal.
 */
export const PLACEMENT_HEADING_COUNT = 64;

/** Puts a player's ship at rest on the centre of a navigable tile, with a heading in [0, PLACEMENT_HEADING_COUNT). */
export const testPlacementSchema = z.strictObject({
  code: matchCodeSchema,
  sessionId: z.string().min(1).max(64),
  tileX: z.int().min(0).max(4096),
  tileY: z.int().min(0).max(4096),
  heading: z.int().min(0).max(PLACEMENT_HEADING_COUNT - 1),
});

export type TestPlacement = z.infer<typeof testPlacementSchema>;
import { describe, expect, it } from "vitest";
import { HEADING_COUNT } from "@pirate-sea-race/content";
import { PLACEMENT_HEADING_COUNT, testPlacementSchema } from "@pirate-sea-race/protocol";

// The protocol cannot import content, so the server, which reads both, checks that they agree on the headings.
describe("test placement headings", () => {
  const placement = { code: "K7Q2MX", sessionId: "abc123", tileX: 100, tileY: 76 };
  const accepts = (heading: number) => testPlacementSchema.safeParse({ ...placement, heading }).success;

  it("accepts exactly the simulation's headings, [0, HEADING_COUNT)", () => {
    expect(PLACEMENT_HEADING_COUNT).toBe(HEADING_COUNT);
    expect(accepts(0)).toBe(true);
    expect(accepts(HEADING_COUNT - 1)).toBe(true);
    expect(accepts(HEADING_COUNT)).toBe(false);
    expect(accepts(-1)).toBe(false);
  });
});
  it("is version 4: v3's axes still steer a ship and interact docks it, and the duel messages are new", () => {
    expect(PROTOCOL_VERSION).toBe(4);
    expect(validateInputMessage({ ...valid, moveX: 0, moveY: 0, buttons: Buttons.Interact }, context).ok).toBe(true);
  });
});

describe("test placement requests", () => {
  const placement = { code: "K7Q2MX", sessionId: "abc123", tileX: 100, tileY: 76, heading: 0 };

  it("accepts a placement on a tile with a heading", () => {
    expect(testPlacementSchema.safeParse(placement).success).toBe(true);
    expect(testPlacementSchema.safeParse({ ...placement, heading: PLACEMENT_HEADING_COUNT - 1 }).success).toBe(true);
  });

  it.each([
    ["a fractional tile", { ...placement, tileX: 1.5 }],
    ["a negative tile", { ...placement, tileY: -1 }],
    ["a heading beyond the circle", { ...placement, heading: PLACEMENT_HEADING_COUNT }],
    ["a negative heading", { ...placement, heading: -1 }],
    ["a malformed code", { ...placement, code: "nope" }],
    ["an extra field", { ...placement, speed: 64 }],
  ])("refuses %s", (_label, candidate) => {
    expect(testPlacementSchema.safeParse(candidate).success).toBe(false);
  });
});
