nav=lambda x,y: 0<=x<N and 0<=y<N and g[y][x] in '.D'
# density
obs=[(x,y) for y in range(N) for x in range(N) if g[y][x] in '#%D']
worst=0; bad=[]
for y in range(N):
  for x in range(N):
    if not nav(x,y): continue
    best=10**9
    for dy in range(-12,13):
      for dx in range(-12,13):
        X,Y=x+dx,y+dy
        if 0<=X<N and 0<=Y<N and g[Y][X] in '#%D': best=min(best,dx*dx+dy*dy)
    worst=max(worst,best)
    if best>100: bad.append((x,y))
print('worst', math.sqrt(worst), 'bad', len(bad))
if bad:
  for y in range(55):
    print(''.join('X' if (x,y) in set(bad) else g[y][x] for x in range(56)))
def dij(sx,sy,block=set()):
  c={ (sx,sy):0 }; h=[(0,sx,sy)]
  while h:
    d,x,y=heapq.heappop(h)
    if d>c[(x,y)]: continue
    for dx in (-1,0,1):
      for dy in (-1,0,1):
        if dx==dy==0: continue
        X,Y=x+dx,y+dy
        if not nav(X,Y) or (X,Y) in block: continue
        if dx and dy and (not nav(x+dx,y) or not nav(x,y+dy) or (x+dx,y) in block or (x,y+dy) in block): continue
        nd=d+(362 if dx and dy else 256)
        if nd<c.get((X,Y),1e18): c[(X,Y)]=nd; heapq.heappush(h,(nd,X,Y))
  return c
docks=[(x,y) for y in range(N) for x in range(N) if g[y][x]=='D']
isl=lambda p:(p[0]>55)+2*(p[1]>55)
sp=39*20
C={d:dij(*d) for d in docks}
near={}
for a in docks:
  for b in docks:
    if isl(a)==isl(b): continue
    t=C[a].get(b,1e18)/sp
    near[isl(a)]=min(near.get(isl(a),1e9),t)
print('neighbour s', near)
slots=[(int(s.split(',')[0]),int(s.split(',')[1])) for s in sys.argv[2:]]
slots=slots+[(110-x,y) for x,y in slots]+[(x,110-y) for x,y in slots]+[(110-x,110-y) for x,y in slots]
pts=docks+slots
for s in slots: assert nav(*s), s
CC={p:dij(*p) for p in pts}
lon=max(CC[a].get(b,1e18) for a in pts for b in pts)/sp
print('longest', lon)
print('first dock', max(min(CC[s].get(d,1e18) for d in docks) for s in slots)/sp)
disc={(x,y) for y in range(N) for x in range(N) if (x-55)**2+(y-55)**2<=25}
for a in docks:
  cb=dij(*a,block=disc)
  for b in docks:
    if isl(a)!=isl(b) and not cb.get(b,1e18)>C[a][b]: print('bypass',a,b)
print('open sea share', sum(r.count('.') for r in g)/N/N)
open(sys.argv[1]+'.full','w').write('\n'.join(''.join(r) for r in g))
EOF
