import { it } from "vitest";
import { Terrain, terrainAt } from "@pirate-sea-race/content";
import { AXIS_SCALE, defaultSimulationConfig as config, INTERACT_BUTTON, NOT_DOCKED, sail, tileCentre, hullIsClear } from "./index.js";
it("sweep", () => {
  const dock = config.map.docks.find((d) => d.side === "S" && terrainAt(config.map, d.tileX - 1, d.tileY) === Terrain.Land)!;
  const input = { buttons: INTERACT_BUTTON, moveX: 0, moveY: -AXIS_SCALE };
  const out: string[] = [];
  for (const heading of [44, 45, 46, 47]) {
    let line = `${heading}: `;
    for (let x = (dock.tileX + 1) * 256; x < (dock.tileX + 4) * 256; x += 16) {
      let ok = true;
      for (const dy of [-96, 0, 96]) for (const speed of [0, 15, 25]) {
        let ship = { id: "a", slot: 0, x, y: tileCentre(config, dock.tileX, dock.tileY + 3).y + dy, heading, speed, dock: NOT_DOCKED, mooredThrottle: 0 };
        let steps = 0;
        for (; steps < 400 && ship.dock === NOT_DOCKED; steps++) { ship = sail(config, ship, input); if (!hullIsClear(config, ship.x, ship.y)) ok = false; }
        if (ship.dock !== dock.id) ok = false;
      }
      line += ok ? "." : "X";
    }
    out.push(line);
  }
  console.log(dock, out.join("\n"));
});
EOF
