a="""/** Attaches the one screenshot a scenario's verifier reads. */"""
b="""/**
 * Turns a page's ship to a heading with the keyboard, without throttle, from the HUD's readout: holds left or right
 * until the heading is within `tolerance` units, then lets it settle. The readout lags the server, so a hold can carry
 * past; it then turns back with short taps of the key.
 */
export async function turnTo(page: Page, heading: number, tolerance: number, timeoutMs = 15_000): Promise<Readout> {
  const id = await selfId(page);
  const keys = new Keys(page);
  const deadline = Date.now() + timeoutMs;
  const offBy = (ship: Readout) => ((((heading - ship.heading) % HEADING_COUNT) + HEADING_COUNT + HEADING_COUNT / 2) % HEADING_COUNT) - HEADING_COUNT / 2;
  try {
    for (;;) {
      let ship = (await readout(page, id))!;
      if (Math.abs(offBy(ship)) <= tolerance) {
        // Settled: two readouts a patch apart agree and are still within tolerance.
        await page.waitForTimeout(200);
        const again = (await readout(page, id))!;
        if (again.heading === ship.heading) return again;
        ship = again;
        continue;
      }
      if (Date.now() > deadline) throw new Error(`did not turn to heading ${heading} (at ${ship.heading})`);
      const key = offBy(ship) > 0 ? "ArrowRight" : "ArrowLeft";
      if (Math.abs(offBy(ship)) > 4) {
        await keys.set(key, true);
        await page.waitForTimeout(20);
      } else {
        // Close: a short tap, then wait for the readout to catch up.
        await keys.set(key, true);
        await page.waitForTimeout(40);
        await keys.releaseAll();
        await page.waitForTimeout(150);
      }
      if (Math.abs(offBy((await readout(page, id))!)) <= 4) await keys.releaseAll();
    }
  } finally {
    await keys.releaseAll();
  }
}

/**
 * Records every text the page's dock hint shows from now on, as a player would read it; `dockHintsSeen` returns them.
 * A MutationObserver catches a hint that is shown only briefly.
 */
export async function recordDockHints(page: Page): Promise<void> {
  await page.evaluate(() => {
    const hint = document.querySelector('[data-testid="hud-dock-hint"]')!;
    const seen: string[] = [hint.textContent ?? ""];
    (window as unknown as { __dockHints: string[] }).__dockHints = seen;
    new MutationObserver(() => seen.push(hint.textContent ?? "")).observe(hint, { childList: true, characterData: true, subtree: true });
  });
}

export async function dockHintsSeen(page: Page): Promise<string[]> {
  return page.evaluate(() => (window as unknown as { __dockHints: string[] }).__dockHints);
}

/** Attaches the one screenshot a scenario's verifier reads. */"""
assert s.count(a)==1; s=s.replace(a,b)
open(p,'w').write(s)
EOF

