python3 - <<'EOF'
p='tests/e2e/helpers.ts'
s=open(p).read()
start=s.index("/**\n * Turns a page's ship to a heading")
end=s.index("/**\n * Records every text")
new='''/**
 * Turns a page's ship to a heading with the keyboard, without throttle, from the HUD's readout. The ship turns one
 * heading unit per world step while a turn key is held, so each try holds left or right for about as many world
 * steps as the ship is off, then lets go and waits until two readouts a patch apart agree. The readout and the
 * page's key reads lag, so a hold can fall a unit short or carry one past; the next try corrects it.
 */
export async function turnTo(page: Page, heading: number, tolerance: number, timeoutMs = 20_000): Promise<Readout> {
  const id = await selfId(page);
  const deadline = Date.now() + timeoutMs;
  const stepMs = 1000 / WORLD_STEPS_PER_SECOND;
  const offBy = (ship: Readout) => ((((heading - ship.heading) % HEADING_COUNT) + HEADING_COUNT + HEADING_COUNT / 2) % HEADING_COUNT) - HEADING_COUNT / 2;
  for (;;) {
    let ship = (await readout(page, id))!;
    for (;;) {
      await page.waitForTimeout(2 * stepMs);
      const again = (await readout(page, id))!;
      if (again.heading === ship.heading) break;
      ship = again;
    }
    const off = offBy(ship);
    if (Math.abs(off) <= tolerance) return ship;
    if (Date.now() > deadline) throw new Error(`did not turn to heading ${heading} (at ${ship.heading})`);
    const key = off > 0 ? "ArrowRight" : "ArrowLeft";
    await page.keyboard.down(key);
    await page.waitForTimeout(Math.abs(off) * stepMs - stepMs / 2);
    await page.keyboard.up(key);
  }
}

'''
