function headingOff(from: number, to: number): number {
  return ((((to - from) % HEADING_COUNT) + HEADING_COUNT + HEADING_COUNT / 2) % HEADING_COUNT) - HEADING_COUNT / 2;
}

/** Reads the page's own ship until two readouts two world steps apart show the same heading: it is not turning. */
async function steadyReadout(page: Page, id: string, timeoutMs = 2000): Promise<Readout> {
  const deadline = Date.now() + timeoutMs;
  let ship = (await readout(page, id))!;
  for (;;) {
    await page.waitForTimeout(2 * STEP_MS);
    const again = (await readout(page, id))!;
    if (again.heading === ship.heading || Date.now() > deadline) return again;
    ship = again;
  }
}

/**
 * Sails a page's ship toward a world position with the keyboard only, steering from the HUD's authoritative readout:
 * up when roughly on course and below the wanted speed, a tap of down when well above it, and left or right toward the
 * bearing. The wanted speed falls from full speed as the target nears, so the ship arrives slowly enough to dock. The
 * readout lags the server, more so on a busy machine, so a turn is a hold of as many world steps as the ship is off
 * course, after which it waits for the readout to show the heading steady; braking is one step at a time, never
 * enough to stop the ship. Holding a key on a lagging readout would carry the ship past its course, or brake it to a
 * stop and into reverse.
 */
export async function sailTo(page: Page, target: { x: number; y: number }, options: SailOptions = {}): Promise<Readout> {
  const id = await selfId(page);
  const keys = new Keys(page);
  const deadline = Date.now() + (options.timeoutMs ?? 30_000);
  try {
    for (;;) {
      const ship = await readout(page, id);
      if (ship === undefined) throw new Error("own ship missing from the HUD");
      options.onReadout?.(ship);
      const dx = target.x - ship.x;
      const dy = target.y - ship.y;
      const distance = Math.hypot(dx, dy);
      if (options.within !== undefined && distance <= options.within) return ship;
      if (options.until !== undefined && (await options.until())) return ship;
      if (Date.now() > deadline) throw new Error(`did not reach ${target.x},${target.y} (at ${ship.x},${ship.y})`);
      const bearing = Math.round((Math.atan2(dy, dx) / (2 * Math.PI)) * HEADING_COUNT);
      const turn = headingOff(ship.heading, bearing);
      const wanted = Math.min(shipTuning.maxSpeed, Math.max(ARRIVAL_SPEED, (distance / TILE / FULL_SPEED_TILES) * shipTuning.maxSpeed));
      const onCourse = Math.abs(turn) <= 4;
      await keys.set("ArrowUp", onCourse && ship.speed < wanted - shipTuning.acceleration / 2);
      if (ship.speed > wanted + 2 * shipTuning.braking) {
        await keys.set("ArrowDown", true);
        await page.waitForTimeout(STEP_MS);
        await keys.set("ArrowDown", false);
      }
      if (Math.abs(turn) > 1) {
        const key = turn > 0 ? "ArrowRight" : "ArrowLeft";
        await keys.set(key, true);
        await page.waitForTimeout(Math.min(Math.abs(turn), HEADING_COUNT / 4) * STEP_MS - STEP_MS / 2);
        await keys.set(key, false);
        options.onReadout?.(await steadyReadout(page, id));
      } else {
        await page.waitForTimeout(30);
      }
    }
  } finally {
    await keys.releaseAll();
  }
}

